const remoteData = $('CMS').all().map(i => i.json).filter(i => i.spareCode);
const localData = $('Чтение БД').all().map(i => i.json).filter(i => i.id);

const remoteLookup = new Map(remoteData.map(item => [String(item.spareCode), item]));
const localLookup = new Map(localData.map(item => [String(item.id), item]));

const normalize = val => (val === null || val === undefined ? '' : String(val));

function isModified(remote, local) {
  return (
    normalize(remote.spareName) !== normalize(local.name) ||
    normalize(remote.spareDescription) !== normalize(local.description) ||
    normalize(remote.spareType) !== normalize(local.type) ||
    normalize(remote.spareStatus) !== normalize(local.status) ||
    Number(remote.price) !== Number(local.price) ||
    Number(remote.quantity) !== Number(local.quantity) ||
    normalize(remote.updatedAt) !== normalize(local.updated_at)
  );
}

let insert = [];
let update = [];
let deleteList = [];

for (let [code, remoteObj] of remoteLookup) {
  let localObj = localLookup.get(code);
  if (!localObj) {
    insert.push(remoteObj);
  } else if (localObj.is_deleted || isModified(remoteObj, localObj)) {
    update.push(remoteObj);
  }
}

for (let [code, localObj] of localLookup) {
  if (!remoteLookup.has(code) && !localObj.is_deleted) {
    deleteList.push(code);
  }
}

return [{
  json: {
    remote_total: remoteLookup.size,
    local_total: localLookup.size,
    insert: insert,
    update: update,
    delete: deleteList
  }
}];

const COLUMNS = ['spareCode', 'spareName', 'spareDescription', 'spareType', 'spareStatus', 'price', 'quantity', 'updatedAt'];

const formatValue = val => {
  const strVal = val === null || val === undefined ? '' : String(val);
  return /[;"\r\n]/.test(strVal) ? '"' + strVal.replace(/"/g, '""') + '"' : strVal;
};

const dataset = $input.all().map(el => el.json).filter(row => row.spareCode);
const csvOutput = dataset.map(row => COLUMNS.map(col => formatValue(row[col])).join(';')).join('\n');

return [{ json: { record_count: dataset.length, csv: csvOutput } }];
